-- M28 exact additions are checked before historical catalog normalization.
DO $post_merge_verify$
DECLARE expected record;actual text;relation oid;role_name text;privilege_name text;
BEGIN
 IF NOT EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=28 AND name='post_merge_verification') THEN RAISE EXCEPTION 'Missing post merge verification migration28';END IF;
 FOR expected IN SELECT * FROM(VALUES
  ('post_merge_verifications',$shape1${"acl": ["forge_agent_owner=arwdDxt/forge_agent_owner"], "table": ["r", "p", "forge_agent_owner", false, false, "d", null], "columns": [[1, "post_merge_id", "uuid", -1, true, "", "", "-", "gen_random_uuid()", null], [2, "owner_id", "text", -1, true, "", "", "\"default\"", null, null], [3, "project_alias", "text", -1, true, "", "", "\"default\"", null, null], [4, "source_kind", "text", -1, true, "", "", "\"default\"", null, null], [5, "workflow_id", "uuid", -1, true, "", "", "-", null, null], [6, "source_action_id", "uuid", -1, true, "", "", "-", null, null], [7, "root_task_id", "uuid", -1, true, "", "", "-", null, null], [8, "merge_commit", "text", -1, true, "", "", "\"default\"", null, null], [9, "merge_tree", "text", -1, true, "", "", "\"default\"", null, null], [10, "merge_receipt", "jsonb", -1, true, "", "", "-", null, null], [11, "correlation_id", "uuid", -1, true, "", "", "-", "gen_random_uuid()", null], [12, "status", "text", -1, true, "", "", "\"default\"", "'pending'::text", null], [13, "generation", "integer", -1, true, "", "", "-", "0", null], [14, "worker_id", "text", -1, false, "", "", "\"default\"", null, null], [15, "action_role", "name", -1, false, "", "", "\"C\"", null, null], [16, "lease_token", "uuid", -1, false, "", "", "-", null, null], [17, "lease_role", "name", -1, false, "", "", "\"C\"", null, null], [18, "lease_until", "timestamp with time zone", -1, false, "", "", "-", null, null], [19, "request", "jsonb", -1, false, "", "", "-", null, null], [20, "receipt", "jsonb", -1, false, "", "", "-", null, null], [21, "cancel_requested", "boolean", -1, true, "", "", "-", "false", null], [22, "summary", "text", -1, true, "", "", "\"default\"", "''::text", null], [23, "next_poll_at", "timestamp with time zone", -1, true, "", "", "-", "clock_timestamp()", null], [24, "deadline_at", "timestamp with time zone", -1, true, "", "", "-", "(clock_timestamp() + '01:30:00'::interval)", null], [25, "finish_generation", "integer", -1, false, "", "", "-", null, null], [26, "finish_token", "uuid", -1, false, "", "", "-", null, null], [27, "finish_role", "name", -1, false, "", "", "\"C\"", null, null], [28, "finish_value", "jsonb", -1, false, "", "", "-", null, null], [29, "created_at", "timestamp with time zone", -1, true, "", "", "-", "clock_timestamp()", null], [30, "updated_at", "timestamp with time zone", -1, true, "", "", "-", "clock_timestamp()", null]], "indexes": [["post_merge_verifications_owner_id_project_alias_source_kind_key", true, true, "CREATE UNIQUE INDEX post_merge_verifications_owner_id_project_alias_source_kind_key ON forge_agent.post_merge_verifications USING btree (owner_id, project_alias, source_kind, workflow_id, merge_commit)"], ["post_merge_verifications_pending", true, true, "CREATE INDEX post_merge_verifications_pending ON forge_agent.post_merge_verifications USING btree (owner_id, status, next_poll_at, created_at)"], ["post_merge_verifications_pkey", true, true, "CREATE UNIQUE INDEX post_merge_verifications_pkey ON forge_agent.post_merge_verifications USING btree (post_merge_id)"]], "triggers": null, "constraints": [["post_merge_verifications_check", "c", true, false, false, "CHECK ((((status = 'leased'::text) AND (lease_token IS NOT NULL) AND (lease_role IS NOT NULL) AND (lease_until IS NOT NULL)) OR ((status <> 'leased'::text) AND (lease_token IS NULL) AND (lease_role IS NULL) AND (lease_until IS NULL))))"], ["post_merge_verifications_generation_check", "c", true, false, false, "CHECK (((generation >= 0) AND (generation <= 100000)))"], ["post_merge_verifications_merge_commit_check", "c", true, false, false, "CHECK ((merge_commit ~ '^[0-9a-f]{40}$'::text))"], ["post_merge_verifications_merge_receipt_check", "c", true, false, false, "CHECK ((jsonb_typeof(merge_receipt) = 'object'::text))"], ["post_merge_verifications_merge_tree_check", "c", true, false, false, "CHECK ((merge_tree ~ '^[0-9a-f]{40}$'::text))"], ["post_merge_verifications_owner_id_project_alias_root_task__fkey", "f", true, false, false, "FOREIGN KEY (owner_id, project_alias, root_task_id) REFERENCES forge_agent.coding_tasks(owner_id, project_alias, id)"], ["post_merge_verifications_owner_id_project_alias_source_kind_key", "u", true, false, false, "UNIQUE (owner_id, project_alias, source_kind, workflow_id, merge_commit)"], ["post_merge_verifications_pkey", "p", true, false, false, "PRIMARY KEY (post_merge_id)"], ["post_merge_verifications_receipt_check", "c", true, false, false, "CHECK (((receipt IS NULL) OR ((jsonb_typeof(receipt) = 'object'::text) AND (octet_length((receipt)::text) <= 262144))))"], ["post_merge_verifications_request_check", "c", true, false, false, "CHECK (((request IS NULL) OR ((jsonb_typeof(request) = 'object'::text) AND (octet_length((request)::text) <= 65536))))"], ["post_merge_verifications_source_kind_check", "c", true, false, false, "CHECK ((source_kind = ANY (ARRAY['native'::text, 'external'::text])))"], ["post_merge_verifications_status_check", "c", true, false, false, "CHECK ((status = ANY (ARRAY['pending'::text, 'leased'::text, 'passed'::text, 'failed'::text, 'superseded'::text])))"], ["post_merge_verifications_summary_check", "c", true, false, false, "CHECK ((octet_length(summary) <= 4096))"]]}$shape1$),
  ('post_merge_verification_grants',$shape1${"acl": ["forge_agent_owner=arwdDxt/forge_agent_owner"], "table": ["r", "p", "forge_agent_owner", false, false, "d", null], "columns": [[1, "worker_role", "name", -1, true, "", "", "\"C\"", null, null], [2, "owner_id", "text", -1, true, "", "", "\"default\"", null, null], [3, "project_alias", "text", -1, true, "", "", "\"default\"", null, null], [4, "enabled", "boolean", -1, true, "", "", "-", "false", null]], "indexes": [["post_merge_verification_grants_pkey", true, true, "CREATE UNIQUE INDEX post_merge_verification_grants_pkey ON forge_agent.post_merge_verification_grants USING btree (worker_role, owner_id, project_alias)"]], "triggers": null, "constraints": [["post_merge_verification_grants_pkey", "p", true, false, false, "PRIMARY KEY (worker_role, owner_id, project_alias)"]]}$shape1$),
  ('post_merge_remediations',$shape1${"acl": ["forge_agent_owner=arwdDxt/forge_agent_owner"], "table": ["r", "p", "forge_agent_owner", false, false, "d", null], "columns": [[1, "post_merge_id", "uuid", -1, true, "", "", "-", null, null], [2, "owner_id", "text", -1, true, "", "", "\"default\"", null, null], [3, "project_alias", "text", -1, true, "", "", "\"default\"", null, null], [4, "workflow_id", "uuid", -1, true, "", "", "-", null, null], [5, "root_task_id", "uuid", -1, true, "", "", "-", null, null], [6, "merge_commit", "text", -1, true, "", "", "\"default\"", null, null], [7, "summary", "text", -1, true, "", "", "\"default\"", null, null], [8, "receipt", "jsonb", -1, true, "", "", "-", null, null], [9, "created_at", "timestamp with time zone", -1, true, "", "", "-", "clock_timestamp()", null]], "indexes": [["post_merge_remediations_pkey", true, true, "CREATE UNIQUE INDEX post_merge_remediations_pkey ON forge_agent.post_merge_remediations USING btree (post_merge_id)"]], "triggers": null, "constraints": [["post_merge_remediations_pkey", "p", true, false, false, "PRIMARY KEY (post_merge_id)"], ["post_merge_remediations_post_merge_id_fkey", "f", true, false, false, "FOREIGN KEY (post_merge_id) REFERENCES forge_agent.post_merge_verifications(post_merge_id)"], ["post_merge_remediations_receipt_check", "c", true, false, false, "CHECK (((jsonb_typeof(receipt) = 'object'::text) AND (octet_length((receipt)::text) <= 262144)))"], ["post_merge_remediations_summary_check", "c", true, false, false, "CHECK ((octet_length(summary) <= 4096))"]]}$shape1$))x(name,shape) LOOP
  relation:=to_regclass('forge_agent.'||expected.name);
 IF EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=31) THEN
  SELECT jsonb_build_object(
 'table',jsonb_build_array(c.relkind,c.relpersistence,pg_get_userbyid(c.relowner),c.relrowsecurity,c.relforcerowsecurity,c.relreplident,c.reloptions),
 'acl',(SELECT jsonb_agg(item::text ORDER BY item::text) FROM unnest(coalesce(c.relacl,acldefault('r',c.relowner))) item WHERE item::text<>'muse_events=r/forge_agent_owner'),
 'columns',(SELECT jsonb_agg(jsonb_build_array(a.attnum,a.attname,a.atttypid::regtype::text,a.atttypmod,a.attnotnull,a.attidentity,a.attgenerated,a.attcollation::regcollation::text,pg_get_expr(d.adbin,d.adrelid),a.attacl) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON(d.adrelid,d.adnum)=(a.attrelid,a.attnum) WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
 'constraints',(SELECT jsonb_agg(jsonb_build_array(k.conname,k.contype,k.convalidated,k.condeferrable,k.condeferred,forge_agent._retry_legacy_constraint(k.conrelid,k.conname,pg_get_constraintdef(k.oid,false))) ORDER BY k.conname) FROM pg_constraint k WHERE k.conrelid=c.oid),
 'indexes',(SELECT jsonb_agg(jsonb_build_array(ic.relname,i.indisvalid,i.indisready,pg_get_indexdef(i.indexrelid)) ORDER BY ic.relname) FROM pg_index i JOIN pg_class ic ON ic.oid=i.indexrelid WHERE i.indrelid=c.oid),
 'triggers',(SELECT jsonb_agg(jsonb_build_array(t.tgname,t.tgenabled,pg_get_triggerdef(t.oid,false)) ORDER BY t.tgname) FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal AND NOT(t.tgname='delivery_post_merge_sync' AND c.oid='forge_agent.post_merge_verifications'::regclass AND EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=29)))
 )::text INTO actual FROM pg_class c WHERE c.oid=relation;
 ELSE
  SELECT jsonb_build_object(
 'table',jsonb_build_array(c.relkind,c.relpersistence,pg_get_userbyid(c.relowner),c.relrowsecurity,c.relforcerowsecurity,c.relreplident,c.reloptions),
 'acl',(SELECT jsonb_agg(item::text ORDER BY item::text) FROM unnest(coalesce(c.relacl,acldefault('r',c.relowner))) item WHERE item::text<>'muse_events=r/forge_agent_owner'),
 'columns',(SELECT jsonb_agg(jsonb_build_array(a.attnum,a.attname,a.atttypid::regtype::text,a.atttypmod,a.attnotnull,a.attidentity,a.attgenerated,a.attcollation::regcollation::text,pg_get_expr(d.adbin,d.adrelid),a.attacl) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON(d.adrelid,d.adnum)=(a.attrelid,a.attnum) WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
 'constraints',(SELECT jsonb_agg(jsonb_build_array(k.conname,k.contype,k.convalidated,k.condeferrable,k.condeferred,pg_get_constraintdef(k.oid,false)) ORDER BY k.conname) FROM pg_constraint k WHERE k.conrelid=c.oid),
 'indexes',(SELECT jsonb_agg(jsonb_build_array(ic.relname,i.indisvalid,i.indisready,pg_get_indexdef(i.indexrelid)) ORDER BY ic.relname) FROM pg_index i JOIN pg_class ic ON ic.oid=i.indexrelid WHERE i.indrelid=c.oid),
 'triggers',(SELECT jsonb_agg(jsonb_build_array(t.tgname,t.tgenabled,pg_get_triggerdef(t.oid,false)) ORDER BY t.tgname) FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal AND NOT(t.tgname='delivery_post_merge_sync' AND c.oid='forge_agent.post_merge_verifications'::regclass AND EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=29)))
 )::text INTO actual FROM pg_class c WHERE c.oid=relation;
 END IF;
  IF actual IS DISTINCT FROM expected.shape THEN RAISE EXCEPTION 'Post merge relation drift: %',expected.name;END IF;
  FOREACH role_name IN ARRAY ARRAY['forge_agent','forge_coding_worker','forge_coding_reconciler','forge_gpu_worker','public'] LOOP
   FOREACH privilege_name IN ARRAY ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER'] LOOP
    IF has_table_privilege(role_name,relation,privilege_name) OR(privilege_name IN('SELECT','INSERT','UPDATE','REFERENCES') AND has_any_column_privilege(role_name,relation,privilege_name)) THEN RAISE EXCEPTION 'Unexpected post merge table privilege: % % %',role_name,expected.name,privilege_name;END IF;
   END LOOP;
  END LOOP;
 END LOOP;
 FOR expected IN SELECT * FROM(VALUES
  ('forge_agent.post_merge_external_signal()','["forge_agent_owner", true, ["search_path=pg_catalog, pg_temp"], ["forge_agent_owner=X/forge_agent_owner"]]'),
  ('forge_agent.post_merge_lock(uuid)','["forge_agent_owner", true, ["search_path=pg_catalog, pg_temp"], ["forge_agent_owner=X/forge_agent_owner"]]'),
  ('forge_agent.post_merge_native_signal()','["forge_agent_owner", true, ["search_path=pg_catalog, pg_temp"], ["forge_agent_owner=X/forge_agent_owner"]]'),
  ('forge_coding_reconciler_api.post_merge_available(text)','["forge_agent_owner", true, ["search_path=pg_catalog, pg_temp"], ["forge_agent_owner=X/forge_agent_owner", "forge_coding_reconciler=X/forge_agent_owner"]]'),
  ('forge_coding_reconciler_api.post_merge_checkpoint(uuid,integer,uuid,jsonb)','["forge_agent_owner", true, ["search_path=pg_catalog, pg_temp"], ["forge_agent_owner=X/forge_agent_owner", "forge_coding_reconciler=X/forge_agent_owner"]]'),
  ('forge_coding_reconciler_api.post_merge_claim(text)','["forge_agent_owner", true, ["search_path=pg_catalog, pg_temp"], ["forge_agent_owner=X/forge_agent_owner", "forge_coding_reconciler=X/forge_agent_owner"]]'),
  ('forge_coding_reconciler_api.post_merge_finish(uuid,integer,uuid,text,jsonb,text)','["forge_agent_owner", true, ["search_path=pg_catalog, pg_temp"], ["forge_agent_owner=X/forge_agent_owner", "forge_coding_reconciler=X/forge_agent_owner"]]'),
  ('forge_coding_reconciler_api.post_merge_renew(uuid,integer,uuid)','["forge_agent_owner", true, ["search_path=pg_catalog, pg_temp"], ["forge_agent_owner=X/forge_agent_owner", "forge_coding_reconciler=X/forge_agent_owner"]]'),
  ('forge_coding_reconciler_api.post_merge_start_allowed(uuid,integer,uuid)','["forge_agent_owner", true, ["search_path=pg_catalog, pg_temp"], ["forge_agent_owner=X/forge_agent_owner", "forge_coding_reconciler=X/forge_agent_owner"]]'))x(signature,shape) LOOP
  SELECT jsonb_build_array(pg_get_userbyid(p.proowner),p.prosecdef,p.proconfig,ARRAY(SELECT unnest(p.proacl::text[]) ORDER BY 1))::text INTO actual FROM pg_proc p WHERE p.oid=to_regprocedure(expected.signature);
  IF actual IS DISTINCT FROM expected.shape THEN RAISE EXCEPTION 'Post merge function drift: %',expected.signature;END IF;
 END LOOP;
 FOR expected IN SELECT * FROM(VALUES
  ('post_merge_external_confirmed','CREATE TRIGGER post_merge_external_confirmed AFTER UPDATE ON forge_external_workflow.workflows FOR EACH ROW EXECUTE FUNCTION forge_agent.post_merge_external_signal()'),
  ('post_merge_native_confirmed','CREATE TRIGGER post_merge_native_confirmed AFTER UPDATE ON forge_agent.coding_workflow_actions FOR EACH ROW EXECUTE FUNCTION forge_agent.post_merge_native_signal()'))x(name,shape) LOOP
  SELECT pg_get_triggerdef(t.oid,false) INTO actual FROM pg_trigger t
  WHERE t.tgname=expected.name AND t.tgrelid=CASE WHEN expected.name='post_merge_native_confirmed' THEN 'forge_agent.coding_workflow_actions'::regclass ELSE 'forge_external_workflow.workflows'::regclass END AND t.tgenabled='O' AND NOT t.tgisinternal;
  IF actual IS DISTINCT FROM expected.shape THEN RAISE EXCEPTION 'Post merge trigger drift: %',expected.name;END IF;
 END LOOP;
END;
$post_merge_verify$;
